"""Generate the PyInstaller Windows version-info file from VERSION (I3).

Standalone (no PyInstaller import) so it can be unit tested on any platform; PyInstaller
only needs the resulting text file when it builds the .exe on Windows.
"""

from __future__ import annotations

from pathlib import Path

COMPANY_NAME = "thevenom"
PRODUCT_NAME = "OrbitRx Propagation Monitor"
LEGAL_COPYRIGHT = "Copyright (C) 2026 thevenom"
ORIGINAL_FILENAME = "OrbitRxMonitor.exe"

_TEMPLATE = """# UTF-8
#
# Generated by tools/make_version_info.py from VERSION. Do not edit by hand.
VSVersionInfo(
  ffi=FixedFileInfo(
    filevers=({tuple4}),
    prodvers=({tuple4}),
    mask=0x3f,
    flags=0x0,
    OS=0x40004,
    fileType=0x1,
    subtype=0x0,
    date=(0, 0)
    ),
  kids=[
    StringFileInfo(
      [
      StringTable(
        u'040904B0',
        [StringStruct(u'CompanyName', u'{company}'),
        StringStruct(u'FileDescription', u'{product}'),
        StringStruct(u'FileVersion', u'{file_version}'),
        StringStruct(u'InternalName', u'{internal_name}'),
        StringStruct(u'LegalCopyright', u'{copyright}'),
        StringStruct(u'OriginalFilename', u'{original_filename}'),
        StringStruct(u'ProductName', u'{product}'),
        StringStruct(u'ProductVersion', u'{product_version}')])
      ]),
    VarFileInfo([VarStruct(u'Translation', [1033, 1200])])
  ]
)
"""


def version_tuple4(version: str) -> tuple[int, int, int, int]:
    """"5.1.0" -> (5, 1, 0, 0); pads/truncates to exactly 4 ints."""
    parts = [int(p) for p in version.strip().split(".") if p != ""]
    parts = (parts + [0, 0, 0, 0])[:4]
    return tuple(parts)  # type: ignore[return-value]


def build_version_info_text(version: str) -> str:
    tuple4 = ", ".join(str(n) for n in version_tuple4(version))
    return _TEMPLATE.format(
        tuple4=tuple4,
        company=COMPANY_NAME,
        product=PRODUCT_NAME,
        file_version=".".join(str(n) for n in version_tuple4(version)),
        internal_name=Path(ORIGINAL_FILENAME).stem,
        copyright=LEGAL_COPYRIGHT,
        original_filename=ORIGINAL_FILENAME,
        product_version=version.strip(),
    )


def write_version_info(version_file: str | Path, output_file: str | Path) -> Path:
    version = Path(version_file).read_text(encoding="utf-8").strip()
    out = Path(output_file)
    out.write_text(build_version_info_text(version), encoding="utf-8")
    return out


def main() -> None:
    root = Path(__file__).resolve().parents[1]
    write_version_info(root / "VERSION", root / "file_version_info.txt")


if __name__ == "__main__":
    main()
